const raw = $input.all().map((item) => item.json);
const jobs = raw.flatMap((value) => Array.isArray(value) ? value : [value]);
const firstSeenAt = new Date().toISOString();

return jobs
  .filter((job) => job && job.job_id)
  .map((job) => ({
    json: {
      job_id: String(job.job_id),
      company_name: job.company_name ?? '',
      company_slug: job.company_slug ?? '',
      company_url: job.company_url ?? '',
      title: job.title ?? '',
      location: job.location ?? '',
      published_at: job.published_at ?? null,
      job_url: job.job_url ?? '',
      search_keyword: job.search_keyword ?? '',
      search_location: job.search_location ?? '',
      details_status: job.details_status ?? 'not_requested',
      source: job.source ?? 'linkedin',
      scraped_at: job.scraped_at ?? firstSeenAt,
      first_seen_at: firstSeenAt,
      signal_status: 'new'
    }
  }));

const jobs = $('Keep Jobs Not Yet Stored').all().map((item) => item.json);
const grouped = new Map();
const maxJobsPerCompany = 20;

for (const job of jobs) {
  const company = job.company_name || job.company_slug || 'Unknown company';
  if (!grouped.has(company)) grouped.set(company, []);
  grouped.get(company).push(job);
}

return [...grouped.entries()].map(([company, companyJobs]) => {
  const visibleJobs = companyJobs.slice(0, maxJobsPerCompany);
  const lines = visibleJobs.map((job) => {
    const location = job.location ? ` — ${job.location}` : '';
    const published = job.published_at ? ` — ${job.published_at}` : '';
    return `• <${job.job_url}|${job.title}>${location}${published}`;
  });
  const remaining = companyJobs.length - visibleJobs.length;
  if (remaining > 0) lines.push(`• _${remaining} additional new job${remaining === 1 ? '' : 's'} stored in the database_`);

  return {
    json: {
      company_name: company,
      new_jobs_count: companyJobs.length,
      slack_message: `*${company}: ${companyJobs.length} new LinkedIn job${companyJobs.length === 1 ? '' : 's'}*\n\n${lines.join('\n')}\n\n_<https://apify.com/curly/linkedin-jobs-scraper|Collected with Curly's LinkedIn Jobs Scraper>_`
    }
  };
});
